const initialIdeas = [
 {id:'mars',category:'space',topic:'SpaceX / Mars',title:'Will Starship launch toward Mars before 2029?',description:'A launch is one milestone. Arrival and landing are separate bets.',deadline:'Dec 31, 2028',source:'https://new.spacex.com/content/starship-talks/mars-2026',rules:'Resolves Yes if a SpaceX Starship leaves Earth on a publicly confirmed Mars-bound trajectory by December 31, 2028, 23:59 UTC. Earth orbit, a lunar mission, a stated intention or a canceled launch do not qualify. Launch telemetry and SpaceX mission reporting must establish the destination. A failed arrival can still qualify; this market concerns departure. If no qualifying public evidence exists by the deadline, resolves No.',outcomes:['Yes','No']},
 {id:'robotaxi',category:'machines',topic:'Tesla / Robotaxi',title:'Will Tesla Robotaxi operate in 10 U.S. cities before 2028?',description:'Count real service areas, not launch announcements or private demos.',deadline:'Dec 31, 2027',source:'https://www.tesla.com/support/robotaxi',rules:'Resolves Yes if Tesla provides publicly bookable, paid Robotaxi rides in at least 10 distinct U.S. metropolitan statistical areas by December 31, 2027, 23:59 UTC. The service must permit rides without an in-car human safety driver or monitor; remote assistance is allowed. Use Census metropolitan area definitions, Tesla service-area documentation, and independent evidence of qualifying rides. Adjacent cities within one metro count once. Employee-only testing, announcements and demonstrations do not count. Otherwise resolves No.',outcomes:['Yes','No']},
 {id:'hyperloop',category:'ideas',topic:'Hyperloop / Any builder',title:'Will a passenger Hyperloop open before 2030?',description:'The idea counts, whoever builds it. A test-track ride doesn’t.',deadline:'Dec 31, 2029',source:'https://www.tesla.com/sites/default/files/blog_images/hyperloop-alpha.pdf',rules:'Resolves Yes if any operator runs a reduced-pressure tube transport system carrying paying members of the public between two distinct stations by December 31, 2029, 23:59 UTC. The normal service must be publicly bookable and operated on at least 30 separate days before the deadline. Conventional trains, exhibition rides, test tracks, invitation-only demonstrations and freight-only systems do not qualify. Evidence must include operator timetables or booking records and independent reporting. Otherwise resolves No.',outcomes:['Yes','No']}
];
let marketData = initialIdeas.map(m=>({...m,status:'idea',venue:'Market idea'}));
let topic='home', listing='all', search='', xKind='all';
const escapeHTML = s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL = url=>{try{const u=new URL(url);return u.protocol==='https:'?u.href:'#';}catch{return '#';}};
const probabilityText = p=>String(Number((Number(p)*100).toFixed(1)));
const symbols={space:'↗',machines:'T',ai:'x',ideas:'∞',culture:'✳',x:'@'};

// Motion stays confined to the artwork; the title and navigation remain steady.
function initHeaderDepth(){
 const hero=document.querySelector('.masthead'),scene=hero?.querySelector('.hero-scene');
 if(!scene)return;
 const layers=[...hero.querySelectorAll('[data-depth]')];
 const reduced=matchMedia('(prefers-reduced-motion: reduce)'),finePointer=matchMedia('(hover: hover) and (pointer: fine)');
 let frame=0,visible=false,targetX=0,targetY=0,targetScroll=0,x=0,y=0,scroll=0,lastTime=0;
 const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
 function reset(){cancelAnimationFrame(frame);frame=0;lastTime=0;x=y=scroll=targetX=targetY=targetScroll=0;scene.style.removeProperty('--scene-rx');scene.style.removeProperty('--scene-ry');layers.forEach(layer=>{layer.style.removeProperty('--layer-x');layer.style.removeProperty('--layer-y');});hero.classList.remove('motion-active');}
 function draw(time){
  frame=0;
  if(reduced.matches||!visible||document.hidden){lastTime=0;return;}
  const alpha=lastTime?1-Math.exp(-Math.min(time-lastTime,64)/95):.18;lastTime=time;
  x+=(targetX-x)*alpha;y+=(targetY-y)*alpha;scroll+=(targetScroll-scroll)*alpha;
  const small=hero.clientWidth<700?0.55:1;
  layers.forEach(layer=>{const depth=Number(layer.dataset.depth);layer.style.setProperty('--layer-x',`${(-x*35*depth*small).toFixed(2)}px`);layer.style.setProperty('--layer-y',`${(-y*18*depth*small+scroll*76*depth*small).toFixed(2)}px`);});
  scene.style.setProperty('--scene-rx',`${(y*1.2).toFixed(3)}deg`);scene.style.setProperty('--scene-ry',`${(-x*2).toFixed(3)}deg`);
  if(Math.abs(targetX-x)+Math.abs(targetY-y)+Math.abs(targetScroll-scroll)>.002)frame=requestAnimationFrame(draw);else lastTime=0;
 }
 function schedule(){if(!frame&&visible&&!reduced.matches&&!document.hidden)frame=requestAnimationFrame(draw);}
 function measureScroll(){const r=hero.getBoundingClientRect();targetScroll=clamp((window.scrollY)/(r.height+r.top+window.scrollY),0,1);schedule();}
 hero.addEventListener('pointermove',event=>{if(!finePointer.matches||event.pointerType==='touch'||reduced.matches)return;const r=hero.getBoundingClientRect();targetX=clamp((event.clientX-r.left)/r.width*2-1,-1,1);targetY=clamp((event.clientY-r.top)/r.height*2-1,-1,1);schedule();},{passive:true});
 hero.addEventListener('pointerleave',()=>{targetX=targetY=0;schedule();},{passive:true});
 window.addEventListener('scroll',measureScroll,{passive:true});
 window.addEventListener('resize',measureScroll,{passive:true});
 const observer=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;hero.classList.toggle('motion-active',visible&&!reduced.matches);if(visible)measureScroll();else{cancelAnimationFrame(frame);frame=0;lastTime=0;}},{threshold:0});observer.observe(hero);
 reduced.addEventListener('change',()=>{reset();if(!reduced.matches){hero.classList.toggle('motion-active',visible);measureScroll();}});
 finePointer.addEventListener('change',()=>{targetX=targetY=0;schedule();});
 document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelAnimationFrame(frame);frame=0;lastTime=0;}else measureScroll();});
 window.addEventListener('pagehide',()=>{reset();observer.disconnect();},{once:true});
 window.addEventListener('pageshow',event=>{if(event.persisted){observer.observe(hero);measureScroll();}});
}
initHeaderDepth();

function renderMarkets(){
 const shown=marketData.filter(m=>matchesTopic(m)&&(listing==='all'||m.status===listing)&&(!['x','mentions'].includes(topic)||xKind==='all'||m.xKind===xKind)&&[m.title,m.topic,m.venue,m.description].join(' ').toLowerCase().includes(search));
 document.querySelector('#market-grid').innerHTML=shown.map(m=>`<article class="market-card"><div class="card-top"><span class="tag">${escapeHTML(m.topic)}</span><span class="card-symbol" aria-hidden="true">${symbols[m.category]||'e'}</span></div><div class="card-body"><h3>${escapeHTML(m.title)}</h3><p class="card-description">${escapeHTML(m.description)}</p><div class="card-price">${m.probability!=null?`<div><strong>${probabilityText(m.probability)}<span>%</span></strong><small>${escapeHTML(m.outcomeLabel||'YES / IMPLIED PROBABILITY')}</small></div>`:`<div><div class="idea-price">${m.status==='idea'?'A possibility to price.':'Odds unavailable.'}</div><small>${m.status==='idea'?'PROPOSED · NO ODDS YET':'CHECK AT VENUE'}</small></div>`}<small>${escapeHTML(m.deadline)}</small></div>${m.probability!=null?`<div class="odds-track" aria-hidden="true"><span style="width:${Math.max(0,Math.min(100,m.probability*100))}%"></span></div>`:''}</div><div class="card-footer"><span class="venue-badge ${m.status==='idea'?'idea':''}">${escapeHTML(m.venue)}${m.status==='idea'?' / DRAFT':' / SNAPSHOT'}</span><button data-market="${escapeHTML(m.id)}">${m.status==='idea'?'View proposal':'View market'}</button></div></article>`).join('');
 document.querySelector('#empty').hidden=shown.length>0;document.querySelector('#empty').textContent=topic==='neuralink'&&!search&&listing==='all'?'No Neuralink markets in this edition yet. Browse Home to explore the rest of the Elonverse.':'No matching markets. Try another topic, availability filter or search.';
 document.querySelectorAll('[data-market]').forEach(b=>b.addEventListener('click',()=>openMarket(b.dataset.market)));
}
const topicLabels={home:'Home',neuralink:'Neuralink',spacex:'SpaceX',grok:'Grok Bot',mentions:'Mentions',tesla:'Tesla',hyperloop:'Hyperloop',posts:'Post counts',x:'X activity',culture:'Culture',ideas:'Big ideas'};
function matchesTopic(m){
 const subject=[m.topic,m.title].join(' ');
 if(topic==='home')return true;
 if(topic==='mentions')return m.category==='x'&&['tags','keywords','products'].includes(m.xKind);
 if(topic==='posts')return m.category==='x'&&m.xKind==='volume';
 if(topic==='x')return m.category==='x';
 if(topic==='grok')return m.category==='ai'&&/grok/i.test(subject);
 if(topic==='ideas'||topic==='culture')return m.category===topic;
 return ({neuralink:/neuralink/i,spacex:/spacex|starship/i,tesla:/tesla|optimus|robotaxi|roadster/i,hyperloop:/hyperloop/i})[topic]?.test(subject)||false;
}
function syncXFilters(){document.querySelectorAll('[data-xkind]').forEach(b=>{const on=b.dataset.xkind===xKind;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on));b.hidden=topic==='mentions'&&b.dataset.xkind==='volume';if(b.dataset.xkind==='all')b.textContent=topic==='mentions'?'All mentions':'All X activity';});document.querySelector('.x-filters').hidden=topic==='posts';}
function setTopic(value){
 if(!(value in topicLabels))return;
 topic=value;listing='all';search='';xKind='all';document.querySelector('#market-search').value='';
 document.querySelectorAll('[data-topic]').forEach(b=>{const on=b.dataset.topic===value;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on));});
 document.querySelectorAll('[data-status]').forEach(b=>{const on=b.dataset.status==='all';b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on));});
 document.querySelector('#markets-title').textContent=value==='home'?'Price the possibility.':value==='posts'?'Post count predictions.':topicLabels[value]+' predictions.';
 const active=document.querySelector('[data-topic="'+value+'"]'),rail=document.querySelector('.topic-rail');if(active){const a=active.getBoundingClientRect(),r=rail.getBoundingClientRect();if(a.left<r.left||a.right>r.right)active.scrollIntoView({block:'nearest',inline:'nearest',behavior:'instant'});}
 document.querySelector('#x-panel').hidden=!['x','mentions','posts'].includes(value);syncXFilters();renderMarkets();
}
function goToMarkets(){document.querySelector('#markets').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
document.querySelectorAll('[data-topic]').forEach(b=>b.addEventListener('click',()=>{setTopic(b.dataset.topic);goToMarkets();}));
document.querySelectorAll('[data-status]').forEach(b=>b.addEventListener('click',()=>{listing=b.dataset.status;document.querySelectorAll('[data-status]').forEach(x=>{const on=x.dataset.status===listing;x.classList.toggle('active',on);x.setAttribute('aria-pressed',String(on));});renderMarkets();}));
document.querySelectorAll('[data-xkind]').forEach(b=>b.addEventListener('click',()=>{xKind=b.dataset.xkind;document.querySelectorAll('[data-xkind]').forEach(x=>{const on=x.dataset.xkind===xKind;x.classList.toggle('active',on);x.setAttribute('aria-pressed',String(on));});renderMarkets();}));
document.querySelector('#show-x').addEventListener('click',()=>{search='';document.querySelector('#market-search').value='';setTopic('x');});
document.querySelector('#market-search').addEventListener('input',e=>{search=e.target.value.toLowerCase().trim();renderMarkets();});
document.querySelector('#show-culture').addEventListener('click',()=>{search='';document.querySelector('#market-search').value='';setTopic('culture');document.querySelector('#markets').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});});
function openMarket(id){const m=marketData.find(x=>x.id===id);if(!m)return;const draft=m.status==='idea';document.querySelector('#dialog-content').innerHTML=`<span class="eyebrow">${escapeHTML(m.topic)} / ${draft?'PROPOSED MARKET':'PROVIDER LISTING'}</span><h2 id="dialog-title">${escapeHTML(m.title)}</h2><p>${escapeHTML(m.description)}</p>${m.probability!=null?`<p><strong>${probabilityText(m.probability)}% ${escapeHTML(m.outcomeLabel||'Yes')}</strong> · provider snapshot, not an executable quote</p>`:''}<h3>${draft?'Proposed resolution criteria':'Rule summary · confirm at provider'}</h3><p>${escapeHTML(m.rules||'Read the provider’s exact rules and current trading status before taking a position. This research snapshot is not a substitute for those rules.')}</p>${m.outcomes?`<h3>Outcomes</h3><ul>${m.outcomes.map(o=>`<li>${escapeHTML(o)}</li>`).join('')}</ul>`:''}<h3>Deadline</h3><p>${escapeHTML(m.deadline)}</p>${m.url?`<a class="dialog-action" href="${safeURL(m.url)}" target="_blank" rel="noopener noreferrer">Open on ${escapeHTML(m.venue)}</a>`:''}${m.source?`<a href="${safeURL(m.source)}" target="_blank" rel="noopener noreferrer">${draft?'Background source':'Provider rules & evidence'}</a>`:''}<div class="dialog-provenance">${draft?'Draft proposal. Not created or funded. Final source and duplicate checks are required before launch.':`Checked ${escapeHTML(m.checkedAt?new Date(m.checkedAt).toLocaleString('en-US',{timeZone:'America/Los_Angeles',timeZoneName:'short'}):'October 2, 2026')}. Odds and availability may have changed.`}</div>`;document.querySelector('#market-dialog').showModal();}
document.querySelector('.dialog-close').addEventListener('click',()=>document.querySelector('#market-dialog').close());
document.querySelector('#market-dialog').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close();}});
const perpDefs=[{coin:'xyz:TSLA',name:'Tesla',venue:'trade[XYZ]',url:'https://app.hyperliquid.xyz/trade/xyz:TSLA',dex:'xyz'},{coin:'xyz:SPCX',name:'SpaceX',venue:'trade[XYZ]',url:'https://app.hyperliquid.xyz/trade/xyz:SPCX',dex:'xyz'},{coin:'DOGE',name:'Dogecoin',venue:'Hyperliquid',url:'https://app.hyperliquid.xyz/trade/DOGE',dex:''}];
const usd=(n,d=2)=>Number.isFinite(Number(n))?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:d,minimumFractionDigits:d}).format(Number(n)):'—';
const compactUSD=n=>Number.isFinite(Number(n))?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',notation:'compact',maximumFractionDigits:1}).format(Number(n)):'—';
let perpData={},lastPerpTime=null;
function renderPerps(){document.querySelector('#perp-grid').innerHTML=perpDefs.map(d=>{const p=perpData[d.coin];const pct=p&&Number(p.prevDayPx)>0?(Number(p.markPx)/Number(p.prevDayPx)-1)*100:null;return `<article class="perp-card"><div class="perp-top"><b>${escapeHTML(d.coin.split(':').pop())}–PERP</b><span>${escapeHTML(d.venue)}</span></div><h3>${d.name}</h3><div class="perp-mark"><strong>${p?usd(p.markPx,d.coin==='DOGE'?5:2):'—'}</strong><span class="perp-change ${pct<0?'negative':''}">${pct!=null?`${pct>=0?'+':''}${pct.toFixed(2)}% / 24h`:'Venue data unavailable'}</span></div><div class="perp-metrics"><div><small>24H VOLUME</small><span>${p?compactUSD(p.dayNtlVlm):'—'}</span></div><div><small>FUNDING / HOUR</small><span>${p&&Number.isFinite(Number(p.funding))?`${(Number(p.funding)*100).toFixed(4)}%`:'—'}</span></div></div><small class="perp-updated">${p?'Data: '+new Date(p._fetchedAt||lastPerpTime).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'}):'Check current availability at venue'}</small><a href="${d.url}" target="_blank" rel="noopener noreferrer">View ${d.coin.split(':').pop()} at venue</a></article>`;}).join('');}
async function refreshPerps(){const btn=document.querySelector('#refresh-perps');btn.disabled=true;document.querySelector('#perp-status').textContent='Refreshing venue data…';const results=await Promise.allSettled(['xyz',''].map(async dex=>{const r=await fetch('https://api.hyperliquid.xyz/info',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type:'metaAndAssetCtxs',...(dex?{dex}:{})}),signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('Venue unavailable');const a=await r.json();if(!Array.isArray(a)||!a[0]?.universe||!Array.isArray(a[1]))throw Error('Unexpected venue response');const output={};a[0].universe.forEach((m,i)=>{if(perpDefs.some(d=>d.coin===m.name)&&!m.isDelisted&&a[1][i]&&Number(a[1][i].markPx)>0)output[m.name]={...a[1][i],_fetchedAt:new Date().toISOString()};});return output;}));let count=0;results.forEach(r=>{if(r.status==='fulfilled'){Object.assign(perpData,r.value);count+=Object.keys(r.value).length;}});if(count)lastPerpTime=new Date();renderPerps();document.querySelector('#perp-status').textContent=count===3?`Venue data · ${lastPerpTime.toLocaleTimeString([], {hour:'numeric',minute:'2-digit',timeZoneName:'short'})} · refresh to update`:count?`Partial update · ${count}/3 contracts fetched; other figures may be older`:'Refresh unavailable. Displayed figures are the saved snapshot; confirm at the venue.';btn.disabled=false;}
async function loadCatalog(){try{const r=await fetch('catalog.json');if(!r.ok)throw Error();const data=await r.json();if(Array.isArray(data.markets)&&data.markets.length)marketData=data.markets;perpData=data.perps||{};lastPerpTime=data.perpCheckedAt?new Date(data.perpCheckedAt):null;document.querySelector('#snapshot-label').textContent=data.snapshotLabel||'Research edition · October 2, 2026';}catch{}renderMarkets();renderPerps();refreshPerps();}
document.querySelector('.site-header .brand').addEventListener('click',()=>setTopic('home'));
renderMarkets();renderPerps();loadCatalog();document.querySelector('#refresh-perps').addEventListener('click',refreshPerps);

if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
 register({name:'search_elonverse_markets',title:'Search Elonverse markets',description:'Read the catalog of provider snapshots and proposed markets. Returns relevant questions, their provenance and links without placing trades.',inputSchema:{type:'object',properties:{query:{type:'string'},category:{type:'string',enum:['all','space','machines','ai','x','ideas','culture']}},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>!['query','category'].includes(k))||('query' in input&&typeof input.query!=='string')||('category' in input&&!['all','space','machines','ai','x','ideas','culture'].includes(input.category)))throw Error('Provide a text query and a supported category.');return marketData.filter(m=>(!input.category||input.category==='all'||m.category===input.category)&&(!input.query||[m.title,m.topic,m.venue].join(' ').toLowerCase().includes(input.query.toLowerCase()))).map(({id,title,status,venue,deadline,probability,outcomeLabel,url,checkedAt})=>({id,title,status,venue,deadline,probability,outcomeLabel,url,checkedAt}));}});
 register({name:'show_elonverse_market',title:'Show market details',description:'Open the same market details shown by View market or View proposal. Navigates locally; does not create a market or trade.',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length!==1||typeof input.id!=='string'||!marketData.some(m=>m.id===input.id))throw Error('Unknown market id.');openMarket(input.id);return {id:input.id,detailsOpen:true};}});
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
